#!/usr/bin/env bash
###
# install-naruto-sounds.sh
# Self-contained installer for Naruto sound effects for Claude Code hooks.
# All 15 .wav files are embedded (base64) — no external downloads needed.
# Voice lines from Naruto Shippuden: Ultimate Ninja Storm 2 (Japanese).
#
# Events:
#   SessionStart      → Battle cry / jutsu callout sounds
#   UserPromptSubmit  → Positive vocalizations / yes / thanks
#   Stop              → Victory lines
#   Notification      → Alert sounds (permission prompts only)
#
# Prerequisites:
#   - macOS (uses afplay + base64 -D)
#
# Usage: bash install-naruto-sounds.sh
###
set -euo pipefail

SOUNDS_DIR="$HOME/.claude/hooks/sounds/naruto"
mkdir -p "$SOUNDS_DIR"

echo "Extracting 15 Naruto sound files..."

base64 -D << 'B64EOF' > "$SOUNDS_DIR/Naruto_battlecry01.wav"

B64EOF

base64 -D << 'B64EOF' > "$SOUNDS_DIR/Naruto_battlecry02.wav"

B64EOF

base64 -D << 'B64EOF' > "$SOUNDS_DIR/Naruto_battlecry03.wav"

B64EOF

base64 -D << 'B64EOF' > "$SOUNDS_DIR/Naruto_positivevocalization01.wav"

B64EOF

base64 -D << 'B64EOF' > "$SOUNDS_DIR/Naruto_positivevocalization02.wav"

B64EOF

base64 -D << 'B64EOF' > "$SOUNDS_DIR/Naruto_positivevocalization03.wav"

B64EOF

base64 -D << 'B64EOF' > "$SOUNDS_DIR/Naruto_yes01.wav"

B64EOF

base64 -D << 'B64EOF' > "$SOUNDS_DIR/Naruto_thanks01.wav"

B64EOF

base64 -D << 'B64EOF' > "$SOUNDS_DIR/Naruto_victory01.wav"

B64EOF

base64 -D << 'B64EOF' > "$SOUNDS_DIR/Naruto_victory02.wav"

B64EOF

base64 -D << 'B64EOF' > "$SOUNDS_DIR/Naruto_victory03.wav"

B64EOF

base64 -D << 'B64EOF' > "$SOUNDS_DIR/Naruto_victory04.wav"

B64EOF

base64 -D << 'B64EOF' > "$SOUNDS_DIR/Naruto_victory05.wav"

B64EOF

base64 -D << 'B64EOF' > "$SOUNDS_DIR/Naruto_alert01.wav"

B64EOF

base64 -D << 'B64EOF' > "$SOUNDS_DIR/Naruto_alert02.wav"

B64EOF

echo ""
echo "Done! Naruto sounds installed to $SOUNDS_DIR"
echo "To test: afplay $SOUNDS_DIR/Naruto_battlecry01.wav"
